import React, { useState } from "react";

const AddTransaction = ({ addTransaction }) => {
  const [data, setData] = useState({
    title: "",
    amount: "",
    type: "expense"
  });

  const handleChange = (e) => {
    setData({
      ...data,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    addTransaction(data);
    setData({ title: "", amount: "", type: "expense" });
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        name="title"
        placeholder="Title"
        value={data.title}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      />

      <input
        name="amount"
        placeholder="Amount"
        value={data.amount}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      />

      <select
        name="type"
        value={data.type}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      >
        <option value="expense">Expense</option>
        <option value="income">Income</option>
      </select>

      <button
        style={{
          width: "100%",
          padding: "10px",
          background: "#4CAF50",
          color: "white",
          border: "none",
          borderRadius: "5px"
        }}
      >
        Add Transaction
      </button>
    </form>
  );
};

export default AddTransaction;
